        // Get dynamic hire rates for current town
        var hireRates = { carrierWage: 4, guardWage: 6 };
        try { hireRates = Player.getCaravanHireRates(Player.townId); } catch(e) {}
        var horsesOwned = (Player.inventory || {})['horses'] || 0;
